CREATE TABLE t1(x, y); INSERT INTO t1 VALUES(1, 'one'); INSERT INTO t1 VALUES(1, 'ONE'); INSERT INTO t1 VALUES(2, 'two'); INSERT INTO t1 VALUES(2, 'TWO'); INSERT INTO t1 VALUES(3, 'three'); INSERT INTO t1 VALUES(3, 'THREE'); CREATE TABLE t2_a(k INTEGER PRIMARY KEY, v TEXT); CREATE TABLE t2_b(k INTEGER PRIMARY KEY, v TEXT); CREATE VIEW t2 AS SELECT * FROM t2_a UNION ALL SELECT * FROM t2_b; CREATE TRIGGER t2_insert INSTEAD OF INSERT ON t2 BEGIN INSERT INTO t2_a SELECT new.k, new.v WHERE (new.k%2)==0; INSERT INTO t2_b SELECT new.k, new.v WHERE (new.k%2)==1; END; INSERT INTO t2 VALUES(5, 'v'), (4, 'iv'), (3, 'iii'), (2, 'ii');